{"content": "from typing import Dict, Optional

from pydantic import BaseModel, ValidationInfo, field_validator


class FeatureFlags(BaseModel):
    env: str = "dev"
    rollout: Dict[str, int] = {}
    owner: Optional[str] = None

    @field_validator("rollout")
    @classmethod
    def percent(cls, v: Dict[str, int]) -> Dict[str, int]:
        for item in v.values():
            if not 0 <= item <= 100:
                raise ValueError("rollout must be 0-100")
        return v

    @field_validator("owner", mode="after")
    @classmethod
    def default_owner(cls, v: Optional[str], info: ValidationInfo) -> str:
        return v or f"team-{info.data.get('env', 'dev')}"
"}
